-- Generated by tools/write_source_queries.py from focus/data/datasets.py. Read-only; explicit projection (S05).
SELECT s.name AS schema_name,t.name AS table_name,c.column_id,c.name AS column_name,
 ty.name AS type_name,c.max_length,c.precision,c.scale,c.is_nullable,
 c.is_identity,c.is_computed
FROM sys.tables t JOIN sys.schemas s ON s.schema_id=t.schema_id
JOIN sys.columns c ON c.object_id=t.object_id
JOIN sys.types ty ON ty.user_type_id=c.user_type_id
WHERE s.name='WEB_APP' AND
 (t.name LIKE 'FOCUS%' OR t.name IN ('NEO_GRAPH_REWORK',
 'NEO_SOI_CERT_REQUIREMENTS','NEO_CERT_COURSE_MAP'))
ORDER BY s.name,t.name,c.column_id;
